computefd_gpu.m:
function [ fd0pos,fdmin,temppos ] = computefd_gpu(DEM,satepos,gap)
%迭代寻找地面场景点的0多普勒成像卫星位置，并计算其与地面场景点之间的斜距
row1=size(DEM,1);clomn1=size(DEM,2);
row2=size(satepos,1);
fd0pos=zeros(row1,clomn1,3);
fdmin=ones(row1,clomn1).*(-1);
satexyz=satepos(:,1:3);
satev=satepos(:,4:end);
temppos=zeros(row1,clomn1);

satexyz=gpuArray(satexyz);
fd0pos=gpuArray(fd0pos);
fdmin=gpuArray(fdmin);
satev=gpuArray(satev);
DEM=gpuArray(DEM);
temppos=gpuArray(temppos);

satex=repmat(satexyz(:,1),1,clomn1);
satey=repmat(satexyz(:,2),1,clomn1);
satez=repmat(satexyz(:,3),1,clomn1);
satevx=repmat(satev(:,1),1,clomn1);
satevy=repmat(satev(:,2),1,clomn1);
satevz=repmat(satev(:,3),1,clomn1);

for i=1:row1
        fd=abs((satex-repmat(DEM(i,:,1),row2,1)).*satevx+(satey-repmat(DEM(i,:,2),row2,1)).*satevy+(satez-repmat(DEM(i,:,3),row2,1)).*satevz);        
        [minfd,pos]=min(fd);
        temppos(i,:)=pos;
        fd0pos(i,:,:)=satexyz(pos,1:3);
        fdmin(i,:)=minfd;
end 
fd0pos=gather(fd0pos);
fdmin=gather(fdmin);
temppos=gather(temppos);
end

computeIncidenceAngle.m:
function [sigma] = computeIncidenceAngle(pos,DEM )
%计算卫星天线发射的入射波夹角并计算地面对应的散射系数矩阵
a=size(DEM,1);b=size(DEM,2);
sigma=zeros(a,b);
v1=DEM(2:end,2:end,:)-DEM(1:a-1,1:b-1,:);
v2=DEM(2:end,2:end,:)-DEM(1:a-1,2:end,:);
v3=zeros(size(v1));
% for i=1:size(v1,1)
%     for j=1:size(v1,2)
%        v3(i,j,:)=cross(v2(i,j,:),v1(i,j,:));
%     end
% end
v3=cross(v2,v1);%C=CROSS(A,B)返回向量叉积baiduA和B，即，C = A x B

Terrain=DEM(1:a-1,2:end,:);
heading=sum(Terrain.*v3,3);
heading=double((heading>0));
headingtemp=zeros(size(v3));
headingtemp(:,:,1)=heading;headingtemp(:,:,2)=heading;headingtemp(:,:,3)=heading;
v3=v3.*headingtemp;
Slantrange=pos(1:a-1,2:end,:)-Terrain;
multi=sum(Slantrange.*v3,3);
heading=double(multi>=0);
RangeCs=(sqrt(sum(Slantrange.^2,3)).*sqrt(sum(v3.^2,3)));
AngleCs=acos(multi./RangeCs)/pi*180;%求出cs点与该点的斜距之间的夹角
SigmaCs=reflectivity(AngleCs);%利用子函数求出不同入射夹角对应的散射系数
SigmaCs=10.^(SigmaCs/10);
SigmaCs=SigmaCs.*heading;
sigma(1:a-1,2:end)=SigmaCs;
end

computeLos.m:
function [LOS] = computeLos(pos,DEM)
Slantrange=pos-DEM;
temp1=sqrt(sum(Slantrange.^2,3));%sum(A,3)运算后的值为每个通道对应位置的值各自相加
temp(:,:,1)=temp1;temp(:,:,2)=temp1;temp(:,:,3)=temp1;
LOS=Slantrange./temp;%得到了每个斜距的单位矢量
end

