while (cutImage(center(1)-gap,center(2)-gap)&cutImage(center(1)+gap,center(2)-gap)...
       &cutImage(center(1)-gap,center(2)+gap)&cutImage(center(1)+gap,center(2)+gap))
   gap=gap+5;
end
