functions/ploy_regress.m:
function [ Sat_pos ] = ploy_regress( tt,Satpos,t_UTC )
N = length(tt);
X = [ones(N,1)  tt'  (tt').^2  (tt').^3];
Y = Satpos';
a = regress(Y,X);   % Y = X*a
Sat_pos = a(1)*ones(size(t_UTC)) + a(2)*t_UTC + a(3)*t_UTC.^2 + a(4)*t_UTC.^3;
end

functions/Polyfit_Orbit.m:
function [coef]  = Polyfit_Orbit(orbit)
%t0 = (datenum(strrep(xml.swathTiming.burstList.burst(1).azimuthTime,'T',' '))-datenum('2018/0/0 00:00:00)'))*86400; %作用

t = (orbit(:,1) - orbit(1,1)).*10000;
xp = orbit(:,2);
yp = orbit(:,3);
zp = orbit(:,4);
xv = orbit(:,5);
yv = orbit(:,6);
zv = orbit(:,7);
x = [ones(size(orbit,1),1),t,t.*t,t.*t.*t,t.*t.*t.*t,t.*t.*t.*t.*t];
%x = [ones(size(orbit,1),1),t,t.*t,t.*t.*t,t.*t.*t.*t];

[b1,~,~,~,~] = regress(xp,x);
[b2,~,~,~,~]  = regress(yp,x);
[b3,~,~,~,~]  = regress(zp,x);
[b4,~,~,~,~]  = regress(xv,x);
[b5,~,~,~,~]  = regress(yv,x);
[b6,~,~,~,~]  = regress(zv,x);
coef = [b1,b2,b3,b4,b5,b6];
end

functions/real_coherent.m:
function [move_r,move_c,normcor] = real_coherent(image1,image2,figshow)
% 逐点的滑动窗相关计算转化为图像块之间的互相关
figshow = 0;
%% 实相干系数计算（FFT）
[nr,nc] = size(image1); %假设image1与image2大小相同

im1abs = abs(image1);
im2abs = abs(image2);

im1fft = fft2(im1abs);
im2fft = fft2(im2abs);
cor = abs(fftshift(ifft2(im1fft.*conj(im2fft))));
normcor = cor./max(max(cor));
[r,c] = deal(fix(nr/2)+1,fix(nc/2)+1);
[r1,c1,~] = find(normcor == 1);
move_r = r - r1;
move_c = c - c1;
%% 输出
if figshow == 1
    figure;
    imagesc(normcor)
    colormap(jet)
    colorbar
    title('real coherence coefficient','fontWeight','Bold')
end
end

functions/regis_subpixel.m:
function [image2_quantify,image_slave_regis2] = regis_subpixel(image_master,image_slave_regis,nr,nc)
% 精配准(亚像素级)
% blocksize = 128; %子块大小128*128
blocksize = 32; %子块大小ls0104
nrnew = floor(nr/blocksize) * blocksize;
ncnew = floor(nc/blocksize) * blocksize;
% nrnew = 2^nextpow2(nr);
% ncnew = 2^nextpow2(nc);
% temp1 = zeros(nrnew,ncnew);%主
% temp2 = zeros(nrnew,ncnew);%辅
temp1 = image_master(1:nrnew,1:ncnew);%主
temp2 = image_slave_regis(1:nrnew,1:ncnew);%辅
% 分块
image_master_cell = mat2cell(temp1,ones(nrnew/blocksize,1)*blocksize,...
                           ones(ncnew/blocksize,1)*blocksize);
image_slave_cell = mat2cell(temp2,ones(nrnew/blocksize,1)*blocksize,...
                           ones(ncnew/blocksize,1)*blocksize);
% 子块总数
[nsubr,nsubc] = size(image_master_cell);
nsub   = nsubr * nsubc;

sub_r = zeros(nsub,1);    sub_c = zeros(nsub,1);
m = zeros(nsub,1);      n = zeros(nsub,1);     indx = zeros(nsub,1);

% 按列顺序依次提取各子块
for nn = 1:nsub
    image1 = cell2mat(image_master_cell(nn));
    image2 = cell2mat(image_slave_cell(nn));
    % 复图像插值,补零插值
    interptimes = 16;
    [image_interp1] = interp_paddingzero(image1,interptimes);
    [image_interp2] = interp_paddingzero(image2,interptimes);
    % 实相关函数求取偏移量
    [move_r,move_c,~] = real_coherent(image_interp1,image_interp2,0);
    % 亚像素偏移量
    sub_r(nn) = move_r/interptimes;
    sub_c(nn) = move_c/interptimes;
    
    jj = floor(nn/nsubr);    ii = rem(nn,nsubr);
    n(nn) = jj*blocksize + blocksize/2;
    if ii==0
        m(nn) = nsubr*blocksize - blocksize/2;
    else
        m(nn) = (ii-1)*blocksize + blocksize/2;
    end
%  fprintf('(%f,%f)\n',sub_r(nn),sub_c(nn));
    
    image2_interp = interp_cubic(image2,sub_r(nn),sub_c(nn));
    
    [~,coherence] = Calculation_Coherence_Coefficient(image1,image2_interp);
    
    if mean(mean(coherence)) > 0.5
        indx(nn) = 1;
    end
end
idx = (indx > 0);
m = m(idx);    n = n(idx);
sub_r = sub_r(idx);
sub_c = sub_c(idx);
[a,b,c,d,e,f] = all_subpixel_move(m,n,sub_r,sub_c);
% 图像插值
image_slave_regis2 = interp_cubic1(image_slave_regis,a,b,c,d,e,f);
%% 输出
% image2_quantify = Image_Quantify(image_slave_regis2,2,2);%精配准后的量化辅图像
image2_quantify = image_quantify(image_slave_regis2);%精配准后的量化辅图像
end

functions/registration_pixel.m:
function [image_master_regis,image_slave_regis,move_r,move_c] = registration_pixel(image_master,image_slave,nr,nc)
% 粗配准(像素级)
% 实相关系数函数求取偏移量
[move_r,move_c,~] = real_coherent(image_master,image_slave,1);
%
image_slave_temp = image_slave;
% 行偏移（竖直移动）
if move_r >= 0
   % 辅图像向上搬移
   image_slave_temp(1:nr-move_r,:) = image_slave(move_r+1:nr,:);
   % 裁剪
   image_master_mid = image_master(1:nr-move_r,:);
   image_slave_mid  = image_slave_temp(1:nr-move_r,:);
elseif move_r < 0
   % 辅图像向下搬移
   image_slave_temp(1-move_r:nr,:) = image_slave(1:nr+move_r,:);
   % 裁剪
   image_master_mid = image_master(1-move_r:nr,:);
   image_slave_mid  = image_slave_temp(1-move_r:nr,:);
end
%
image_slave_temp_mid = image_slave_mid;
% 列偏移（水平移动）
if move_c >= 0
   % 辅图像向左搬移
   image_slave_temp_mid(:,1:nc-move_c) = image_slave_mid(:,move_c+1:nc);
   % 裁剪
   image_master_regis = image_master_mid(:,1:nc-move_c);
   image_slave_regis  = image_slave_temp_mid(:,1:nc-move_c);
elseif move_c < 0
   % 辅图像向右搬移
   image_slave_temp_mid(:,1-move_c:nc) = image_slave_mid(:,1:nc+move_c);
   % 裁剪
   image_master_regis = image_master_mid(:,1-move_c:nc);
   image_slave_regis  = image_slave_temp_mid(:,1-move_c:nc);
end
end

functions/registration_subpixel1.m:
function [image_slave_regis2] = registration_subpixel1(image_master,image_slave_regis)
% 精配准(亚像素级)
blocksize = 96; %子块大小128*128
[nr,nc] = size(image_master);
nrnew = floor(nr/blocksize) * blocksize;%向下取整
ncnew = floor(nc/blocksize) * blocksize;
% nrnew = 2^nextpow2(nr);
% ncnew = 2^nextpow2(nc);
% temp1 = zeros(nrnew,ncnew);               %主
% temp2 = zeros(nrnew,ncnew);               %辅
temp1 = image_master(1:nrnew,1:ncnew);      %主
temp2 = image_slave_regis(1:nrnew,1:ncnew); %辅,使块能取整
% 分块
image_master_cell = mat2cell(temp1,ones(nrnew/blocksize,1)*blocksize,ones(ncnew/blocksize,1)*blocksize);
image_slave_cell = mat2cell(temp2,ones(nrnew/blocksize,1)*blocksize,ones(ncnew/blocksize,1)*blocksize);
%mat2cell为矩阵分块，image_master_cell{1，1}表示第一块
% 子块总数
[nsubr,nsubc] = size(image_master_cell);
nsub   = nsubr * nsubc;

sub_r = zeros(nsub,1);    sub_c = zeros(nsub,1);
m = zeros(nsub,1);        n = zeros(nsub,1);     indx = zeros(nsub,1);

% 按列顺序依次提取各子块
for nn = 1:nsub
    image1 = cell2mat(image_master_cell(nn));
    image2 = cell2mat(image_slave_cell(nn));
    % 复图像插值,补零插值,可增采样
    interptimes = 32;
    [image_interp1] = interp_paddingzero(image1,interptimes);
    [image_interp2] = interp_paddingzero(image2,interptimes);%image_interp2的大小为原图像长和宽的interptimes倍
    % 实相关函数求取偏移量
    [move_r,move_c,~] = real_coherent(image_interp1,image_interp2,0);
    % 亚像素偏移量
    sub_r(nn) = move_r/interptimes;
    sub_c(nn) = move_c/interptimes;
    
    jj = floor(nn/nsubr);    ii = rem(nn,nsubr); % rem是取余，floor向负无穷大方向取整
    n(nn) = jj*blocksize + blocksize/2;%n为每块的中心像素的行数
    if ii==0
        m(nn) = nsubr*blocksize + blocksize/2;%m为每块中心像素的列数？？认为加号应为减号
    else
        m(nn) = (ii-1)*blocksize + blocksize/2;
    end
    %图像第一次插值，找出相关系数高的子块
    image2_interp = interp_cubic(image2,sub_r(nn),sub_c(nn));
    [~,coherence] = Calculation_Coherence_Coefficient(image1,image2_interp);
    if mean(mean(coherence)) > 0.5
        indx(nn) = 1;
    end
end
idx = (indx > 0);
m = m(idx);    n = n(idx);
sub_r = sub_r(idx);
sub_c = sub_c(idx);
[a,b,c,d,e,f] = all_subpixel_move(m,n,sub_r,sub_c);
% 图像插值
image_slave_regis2 = interp_cubic1(image_slave_regis,a,b,c,d,e,f);
%% 输出
end

functions/removeFlat_range.m:
function [phase_removeFlat,Flat_phase_wrapped] = removeFlat_range(interf_phase2)
% 距离向去平地相位
rangefft = fft(interf_phase2.'); % 距离向FFT
% range
[nr3,nc3] = size(rangefft);
spectrumsum = sum(abs(rangefft),2);
nn = nr3;
[r,c,v] = find(spectrumsum == max(spectrumsum));
tempi = (0:nn-1);              % 行线性相位网格
fi = double(r(1)-1)/nn;
j = sqrt(-1);
ei = exp(-j*2*pi*fi);          % 红蓝边界,频率为负;蓝红边界,频率为正.
fp1 = ones(nc3,1)*ei.^tempi;
% phase_removeFlat = angle(image_master.*conj(image_slave_regis2).*fp1(1:nc3,:));
j = sqrt(-1);
phase_removeFlat = angle(exp(j*interf_phase2).*fp1(1:nc3,:));

% figure;
% imagesc(phase_removeFlat)
% colormap(jet)
% title('interferometric phase (remove flat phase)','fontWeight','Bold')
% 去平地后距离谱
rangefft = fftshift(fft(phase_removeFlat.'));
spectrumsum = sum(abs(rangefft),2);
% 缠绕的平地相位
Flat_phase_wrapped = angle(fp1);
% 输出
% if display == 1
%     figure;
%     plot(spectrumsum) %去平地后距离谱
%     title('range spectrum after remove flat phase','fontWeight','Bold')
%     figure;
%     imagesc(Flat_phase_wrapped)%缠绕的距离向平地相位
%     colormap(jet)
%     colorbar
%     title('wrapped flat phase','fontWeight','Bold')
% end
end

