classdef ReLU < dagnn.ElementWise
  properties
    useShortCircuit = true
    leak = 0
    opts = {}
  end

  methods
    function outputs = forward(obj, inputs, params)
      outputs{1} = vl_nnrelu(inputs{1}, [], ...
                             'leak', obj.leak, obj.opts{:}) ;
    end

    function [derInputs, derParams] = backward(obj, inputs, params, derOutputs)
      derInputs{1} = vl_nnrelu(inputs{1}, derOutputs{1}, ...
                               'leak', obj.leak, ...
                               obj.opts{:}) ;
      derParams = {} ;
    end

    function forwardAdvanced(obj, layer)
      if ~obj.useShortCircuit || ~obj.net.conserveMemory
        forwardAdvanced@dagnn.Layer(obj, layer) ;
        return ;
      end
      net = obj.net ;
      in = layer.inputIndexes ;
      out = layer.outputIndexes ;
      net.vars(out).value = vl_nnrelu(net.vars(in).value, [], ...
                                      'leak', obj.leak, ...
                                      obj.opts{:}) ;
      net.numPendingVarRefs(in) = net.numPendingVarRefs(in) - 1;
      if ~net.vars(in).precious & net.numPendingVarRefs(in) == 0
        net.vars(in).value = [] ;
      end
    end

    function backwardAdvanced(obj, layer)
      if ~obj.useShortCircuit || ~obj.net.conserveMemory
        backwardAdvanced@dagnn.Layer(obj, layer) ;
        return ;
      end
      net = obj.net ;
      in = layer.inputIndexes ;
      out = layer.outputIndexes ;

      if isempty(net.vars(out).der), return ; end

      derInput = vl_nnrelu(net.vars(out).value, net.vars(out).der, ...
                           'leak', obj.leak, obj.opts{:}) ;

      if ~net.vars(out).precious
        net.vars(out).der = [] ;
        net.vars(out).value = [] ;
      end

      if net.numPendingVarRefs(in) == 0
          net.vars(in).der = derInput ;
      else
          net.vars(in).der = net.vars(in).der + derInput ;
      end
      net.numPendingVarRefs(in) = net.numPendingVarRefs(in) + 1 ;
    end

    function obj = ReLU(varargin)
      obj.load(varargin) ;
    end
  end
end

classdef Scale < dagnn.ElementWise
  properties
    size
    hasBias = true
  end

  methods

    function outputs = forward(obj, inputs, params)
      args = horzcat(inputs, params) ;
      outputs{1} = bsxfun(@times, args{1}, args{2}) ;
      if obj.hasBias
        outputs{1} = bsxfun(@plus, outputs{1}, args{3}) ;
      end
    end

    function [derInputs, derParams] = backward(obj, inputs, params, derOutputs)
      args = horzcat(inputs, params) ;
      sz = [size(args{2}) 1 1 1 1] ;
      sz = sz(1:4) ;
      dargs{1} = bsxfun(@times, derOutputs{1}, args{2}) ;
      dargs{2} = derOutputs{1} .* args{1} ;
      for k = find(sz == 1)
        dargs{2} = sum(dargs{2}, k) ;
      end
      if obj.hasBias
        dargs{3} = derOutputs{1} ;
        for k = find(sz == 1)
          dargs{3} = sum(dargs{3}, k) ;
        end
      end
      derInputs = dargs(1:numel(inputs)) ;
      derParams = dargs(numel(inputs)+(1:numel(params))) ;
    end

    function obj = Scale(varargin)
      obj.load(varargin) ;
    end
  end
end

