void vl::Tensor::setMemory(void * x) { memory = x ; }
vl::Device vl::Tensor::getDeviceType() const { return deviceType ; }
bool vl::Tensor::isNull() const { return memory == NULL ; }
vl::Tensor::operator bool() const { return !isNull() ; }

