  struct operations<vl::CPU, type>
  {
    typedef type data_type ;

    static vl::Error
    copy(data_type * dest,
         data_type const * src,
         size_t numElements)
    {
      memcpy(dest, src, numElements * sizeof(data_type)) ;
      return vlSuccess ;
    }

    static vl::Error
    fill(data_type * dest,
         size_t numElements,
         data_type value)
    {
      for (size_t k = 0 ; k < numElements ; ++k) {
        dest[k] = value ;
      }
      return vlSuccess ;
    }
  } ;

