the terms of the BSD license (see the COPYING file).
*/

#include "../imread.hpp"
#include "imread_helpers.hpp"

#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <cassert>
#include <algorithm>
extern "C" {
#include <jpeglib.h>
#include <setjmp.h>
}

/* ---------------------------------------------------------------- */
/*                                    LibJPEG reader implementation */
/* ---------------------------------------------------------------- */

#define ERR_MSG_MAX_LEN 1024

class vl::ImageReader::Impl
{
public:
  Impl() ;
  ~Impl() ;
  struct jpeg_error_mgr jpegErrorManager ; /* must be the first element */
  struct jpeg_decompress_struct decompressor ;
  jmp_buf onJpegError ;
  char jpegLastErrorMsg [JMSG_LENGTH_MAX] ;
  char lastErrorMessage [ERR_MSG_MAX_LEN] ;

  vl::Error readPixels(float * memory, char const * filename) ;
  vl::Error readShape(vl::ImageShape & shape, char const * filename) ;

  static void reader_jpeg_error (j_common_ptr cinfo)
  {
    vl::ImageReader::Impl* self = (vl::ImageReader::Impl*) cinfo->err ;
    (*(cinfo->err->format_message)) (cinfo, self->jpegLastErrorMsg) ;
    longjmp(self->onJpegError, 1) ;
  }
} ;

vl::ImageReader::Impl::Impl()
{
  lastErrorMessage[0] = 0 ;
  decompressor.err = jpeg_std_error(&jpegErrorManager) ;
  jpegErrorManager.error_exit = reader_jpeg_error ;
  jpeg_create_decompress(&decompressor) ;
}

vl::ImageReader::Impl::~Impl()
{
  jpeg_destroy_decompress(&decompressor) ;
}

vl::Error
vl::ImageReader::Impl::readPixels(float * memory, char const * filename)
{
  vl::Error error = vl::vlSuccess ;
  int row_stride ;
  const int blockSize = 32 ;
  char unsigned * pixels = NULL ;
  JSAMPARRAY scanlines = NULL ;
  bool requiresAbort = false ;

  /* initialize the image as null */
  ImageShape shape ;

  /* open file */
  FILE* fp = fopen(filename, "r") ;
  if (fp == NULL) {
    error = vl::vlErrorUnknown ;
    return error ;
  }

  /* handle LibJPEG errors */
  if (setjmp(onJpegError)) {
    error = vl::vlErrorUnknown ;
    std::snprintf(lastErrorMessage,  sizeof(lastErrorMessage),
                  "libjpeg: %s", jpegLastErrorMsg) ;
    goto done ;
  }

  /* set which file to read */
  jpeg_stdio_src(&decompressor, fp);

  /* read image metadata */
  jpeg_read_header(&decompressor, TRUE) ;
  requiresAbort = true ;

  /* figure out if the image is grayscale (depth = 1) or color (depth = 3) */
  decompressor.quantize_colors = FALSE ;
  if (decompressor.jpeg_color_space == JCS_GRAYSCALE) {
    shape.depth = 1 ;
    decompressor.out_color_space = JCS_GRAYSCALE ;
  }  else {
    shape.depth = 3 ;
    decompressor.out_color_space = JCS_RGB ;
  }

  /* get the output dimension */
  jpeg_calc_output_dimensions(&decompressor) ;
  shape.width = decompressor.output_width ;
  shape.height = decompressor.output_height ;

  /* allocate scaline buffer */
  pixels = (char unsigned*)malloc(sizeof(char) * shape.width * shape.height * shape.depth) ;
  if (pixels == NULL) {
    error = vl::vlErrorUnknown ;
    goto done ;
  }
  scanlines = (char unsigned**)malloc(sizeof(char*) * shape.height) ;
  if (scanlines == NULL) {
    error = vl::vlErrorUnknown ;
    goto done ;
  }
  for (int y = 0 ; y < shape.height ; ++y) {
    scanlines[y] = pixels + shape.depth * shape.width * y ;
  }

  /* decompress each scanline and transpose the result into MATLAB format */
  jpeg_start_decompress(&decompressor);
  while(decompressor.output_scanline < shape.height) {
    jpeg_read_scanlines(&decompressor,
                        scanlines + decompressor.output_scanline,
                        shape.height - decompressor.output_scanline);
  }
  {
    Image image(shape, memory) ;
    switch (shape.depth) {
    case 3 : vl::impl::imageFromPixels<impl::pixelFormatRGB>(image, pixels, shape.width*3) ; break ;
    case 1 : vl::impl::imageFromPixels<impl::pixelFormatL>(image, pixels, shape.width*1) ; break ;
    default : error = vl::vlErrorUnknown ; goto done ;
    }
    jpeg_finish_decompress(&decompressor) ;
    requiresAbort = false ;
  }

done:
  if (requiresAbort) { jpeg_abort((j_common_ptr)&decompressor) ; }
  if (scanlines) free(scanlines) ;
  if (pixels) free(pixels) ;
  fclose(fp) ;
  return error ;
}

vl::Error
vl::ImageReader::Impl::readShape(vl::ImageShape & shape, char const * filename)
{
  vl::Error error = vl::vlSuccess ;

  int row_stride ;
  const int blockSize = 32 ;
  char unsigned * pixels = NULL ;
  JSAMPARRAY scanlines ;
  bool requiresAbort = false ;

  // open file
  FILE* fp = fopen(filename, "r") ;
  if (fp == NULL) {
    error = vl::vlErrorUnknown ;
    return error ;
  }

  // handle LibJPEG errors
  if (setjmp(onJpegError)) {
    error = vl::vlErrorUnknown ;
    std::snprintf(lastErrorMessage,  sizeof(lastErrorMessage),
                  "libjpeg: %s", jpegLastErrorMsg) ;
    goto done ;
  }

  /* set which file to read */
  jpeg_stdio_src(&decompressor, fp);

  /* read image metadata */
  jpeg_read_header(&decompressor, TRUE) ;
  requiresAbort = true ;

  /* figure out if the image is grayscale (depth = 1) or color (depth = 3) */
  if (decompressor.jpeg_color_space == JCS_GRAYSCALE) {
    shape.depth = 1 ;
  }  else {
    shape.depth = 3 ;
  }

  /* get the output dimension (this may differ from the input if we were to scale the image) */
  jpeg_calc_output_dimensions(&decompressor) ;
  shape.width = decompressor.output_width ;
  shape.height = decompressor.output_height ;

done:
  if (requiresAbort) { jpeg_abort((j_common_ptr)&decompressor) ; }
  fclose(fp) ;
  return error ;
}

/* ---------------------------------------------------------------- */
/*                                                   LibJPEG reader */
/* ---------------------------------------------------------------- */

vl::ImageReader::ImageReader()
: impl(NULL)
{
  impl = new vl::ImageReader::Impl() ;
}

vl::ImageReader::~ImageReader()
{
  delete impl ;
}

vl::Error
vl::ImageReader::readPixels(float * memory, char const * filename)
{
  return impl->readPixels(memory, filename) ;
}

vl::Error
vl::ImageReader::readShape(vl::ImageShape & shape, char const * filename)
{
  return impl->readShape(shape, filename) ;
}

char const *
vl::ImageReader::getLastErrorMessage() const
{
  return impl->lastErrorMessage  ;
}

// @file imread_quartz.cpp
// @brief Image reader based on Apple Quartz (Core Graphics).
// @author Andrea Vedaldi

/*
Copyright (C) 2015-16 Andrea Vedaldi.
All rights reserved.

This file is part of the VLFeat library and is made available under
the terms of the BSD license (see the COPYING file).
*/

#include "../imread.hpp"
#include "imread_helpers.hpp"

#import <ImageIO/ImageIO.h>
#include <algorithm>

#include <iostream>

/* ---------------------------------------------------------------- */
/*                                     Quartz reader implementation */
/* ---------------------------------------------------------------- */

#define check(x) \
if (!(x)) { error = vl::vlErrorUnknown ; goto done ; }

#define ERR_MSG_MAX_LEN 1024

struct vl::ImageReader::Impl
{
  char lastErrorMessage [ERR_MSG_MAX_LEN] ;
  Impl() { lastErrorMessage[0] = 0 ; }
} ;

vl::ImageReader::ImageReader()
: impl(new Impl())
{ }

vl::ImageReader::~ImageReader()
{
  delete(impl) ;
}

const char * vl::ImageReader::getLastErrorMessage() const
{
  return impl->lastErrorMessage ;
}

vl::Error
vl::ImageReader::readPixels(float * memory, const char * fileName)
{
  vl::Error error = vl::vlSuccess ;

  // intermediate buffer
  char unsigned * pixels = NULL ;
  int bytesPerPixel ;
  int bytesPerRow ;

  // Core graphics
  CGBitmapInfo bitmapInfo ;
  CFURLRef url = NULL ;
  CGImageSourceRef imageSourceRef = NULL ;
  CGImageRef imageRef = NULL ;
  CGContextRef contextRef = NULL ;
  CGColorSpaceRef sourceColorSpaceRef = NULL ;
  CGColorSpaceRef colorSpaceRef = NULL ;

  // initialize the image as null
  ImageShape shape ;
  shape.width = 0 ;
  shape.height = 0 ;
  shape.depth = 0 ;

  // get file
  url = CFURLCreateFromFileSystemRepresentation(kCFAllocatorDefault, (const UInt8 *)fileName, strlen(fileName), false) ;
  check(url) ;

  // get image source from file
  imageSourceRef = CGImageSourceCreateWithURL(url, NULL) ;
  check(imageSourceRef) ;

  // get image from image source
  imageRef = CGImageSourceCreateImageAtIndex(imageSourceRef, 0, NULL);
  check(imageRef) ;

  sourceColorSpaceRef = CGImageGetColorSpace(imageRef) ;
  check(sourceColorSpaceRef) ;

  shape.width = CGImageGetWidth(imageRef);
  shape.height = CGImageGetHeight(imageRef);
  shape.depth = CGColorSpaceGetNumberOfComponents(sourceColorSpaceRef) ;
  check(shape.depth == 1 || shape.depth == 3) ;

  // decode image to L (8 bits per pixel) or RGBA (32 bits per pixel)
  switch (shape.depth) {
    case 1:
      colorSpaceRef = CGColorSpaceCreateDeviceGray();
      bytesPerPixel = 1 ;
      bitmapInfo = kCGImageAlphaNone ;
      break ;

    case 3:
      colorSpaceRef = CGColorSpaceCreateDeviceRGB();
      bytesPerPixel = 4 ;
      bitmapInfo = kCGImageAlphaPremultipliedLast || kCGBitmapByteOrder32Big ;
      /* this means
       pixels[0] = R
       pixels[1] = G
       pixels[2] = B
       pixels[3] = A
       */
      break ;
  }
  check(colorSpaceRef) ;

  bytesPerRow = shape.width * bytesPerPixel ;
  pixels = (char unsigned*)malloc(shape.height * bytesPerRow) ;
  check(pixels) ;

  contextRef = CGBitmapContextCreate(pixels,
                                     shape.width, shape.height,
                                     8, bytesPerRow,
                                     colorSpaceRef,
                                     bitmapInfo) ;
  check(contextRef) ;

  CGContextDrawImage(contextRef, CGRectMake(0, 0, shape.width, shape.height), imageRef);

  // copy pixels to MATLAB format
  {
    Image image(shape, memory) ;
    switch (shape.depth) {
      case 3:
        vl::impl::imageFromPixels<impl::pixelFormatRGBA>(image, pixels, shape.width * bytesPerPixel) ;
        break ;
      case 1:
        vl::impl::imageFromPixels<impl::pixelFormatL>(image, pixels, shape.width * bytesPerPixel) ;
        break ;
    }
  }

done:
  if (pixels) { free(pixels) ; }
  if (contextRef) { CFRelease(contextRef) ; }
  if (colorSpaceRef) { CFRelease(colorSpaceRef) ; }
  if (imageRef) { CFRelease(imageRef) ; }
  if (imageSourceRef) { CFRelease(imageSourceRef) ; }
  if (url) { CFRelease(url) ; }
  return error ;
}

vl::Error
vl::ImageReader::readShape(vl::ImageShape & shape, const char * fileName)
{
  vl::Error error = vl::vlSuccess ;

  // intermediate buffer
  char unsigned * rgba = NULL ;

  // Core graphics
  CFURLRef url = NULL ;
  CGImageSourceRef imageSourceRef = NULL ;
  CGImageRef imageRef = NULL ;
  CGColorSpaceRef sourceColorSpaceRef = NULL ;

  // initialize the image as null
  shape.clear() ;

  // get file
  url = CFURLCreateFromFileSystemRepresentation(kCFAllocatorDefault, (const UInt8 *)fileName, strlen(fileName), false) ;
  check(url) ;

  // get image source from file
  imageSourceRef = CGImageSourceCreateWithURL(url, NULL) ;
  check(imageSourceRef) ;

  // get image from image source
  imageRef = CGImageSourceCreateImageAtIndex(imageSourceRef, 0, NULL);
  check(imageRef) ;

  sourceColorSpaceRef = CGImageGetColorSpace(imageRef) ;
  check(sourceColorSpaceRef) ;

  shape.width = CGImageGetWidth(imageRef);
  shape.height = CGImageGetHeight(imageRef);
  shape.depth = CGColorSpaceGetNumberOfComponents(sourceColorSpaceRef) ;
  check(shape.depth == 1 || shape.depth == 3) ;

done:
  if (imageRef) { CFRelease(imageRef) ; }
  if (imageSourceRef) { CFRelease(imageSourceRef) ; }
  if (url) { CFRelease(url) ; }
  return error ;
}

