padTop, padBottom, \
padLeft, padRight) ;

#define DISPATCH2(deviceType) \
switch (dataType) { \
case vlTypeFloat : DISPATCH(deviceType, vlTypeFloat) ; break ; \
IF_DOUBLE(case vlTypeDouble : DISPATCH(deviceType, vlTypeDouble) ; break ;) \
default: assert(false) ; return vlErrorUnknown ; \
}

#define DISPATCHCUDNN(dataType) \
error = vl::impl::nnconv_cudnn<dataType>::forward \
(context, \
 output, outputMult, \
 data, dataMult, \
 filters, biases, \
 strideY, strideX, \
 padTop, padBottom, \
 padLeft, padRight) ;

#define DISPATCHCUDNN2() \
switch (dataType) { \
case vlTypeFloat : DISPATCHCUDNN(vlTypeFloat) ; break ; \
IF_DOUBLE(case vlTypeDouble : DISPATCHCUDNN(vlTypeDouble) ; break ;) \
default: assert(false) ; return vlErrorUnknown ; \
}

vl::Error
vl::nnconv_forward(Context& context,
                   Tensor output, double outputMult,
                   Tensor data, double dataMult,
                   Tensor filters,
                   Tensor biases,
                   int strideY, int strideX,
                   int padTop, int padBottom,
                   int padLeft, int padRight)
{
  vl::Error error = vlSuccess ;
  vl::Type dataType = output.getDataType() ;

  switch (output.getDeviceType()) {
    default:
      assert(false) ;
      error = vl::vlErrorUnknown ;
      break ;

    case vl::CPU:
      DISPATCH2(vl::CPU) ;
      break ;

#if ENABLE_GPU
    case vl::GPU:
#if ENABLE_CUDNN
      if (context.getCudaHelper().getCudnnEnabled()) {
        DISPATCHCUDNN2() ;
        if (error == vl::vlSuccess) { return error ; }
        if (error != vl::vlErrorUnsupported) { goto done ; }
        /* this case was not supported by CUDNN -- fallback */
      }
#endif
      DISPATCH2(vl::GPU) ;
      break ;
#endif
  }
#if ENABLE_CUDNN
done:
#endif
  return error ;
}

/* ---------------------------------------------------------------- */
/*                                                  nnconv_backward */
/* ---------------------------------------------------------------- */


/*
 for derBiases:  must have derOuptut
 for derData:    must have derData, derOutput and filters
 for derFilters: must have derFilters, derOutput and data
 */

#undef DISPATCH
#define DISPATCH(deviceType, dataType) \
error = vl::impl::nnconv_backward_blas<deviceType, dataType> \
(context, \
 derData, derFilters, derBiases, \
 data, filters, derOutput, \
 strideY, strideX, \
 padTop, padBottom, \
 padLeft, padRight) ;

#undef DISPATCHCUDNN
#define DISPATCHCUDNN(dataType) \
error = vl::impl::nnconv_cudnn<dataType>::backward \
(context, \
 derData, derFilters, derBiases, \
 data, filters, derOutput, \
 strideY, strideX, \
 padTop, padBottom, \
 padLeft, padRight) ;

vl::Error
vl::nnconv_backward(Context& context,
                    Tensor derData,
                    Tensor derFilters,
                    Tensor derBiases,
                    Tensor data,
                    Tensor filters,
                    Tensor derOutput,
                    int strideY, int strideX,
                    int padTop, int padBottom,
                    int padLeft, int padRight)
{
  vl::Error error = vl::vlSuccess ;
  vl::Type dataType = derOutput.getDataType() ;

  switch (derOutput.getDeviceType()) {
    default:
      assert(false) ;
      error = vl::vlErrorUnknown ;
      break ;

    case vl::CPU:
      DISPATCH2(vl::CPU) ;
      break ;

#if ENABLE_GPU
    case vl::GPU:
#if ENABLE_CUDNN
      if (context.getCudaHelper().getCudnnEnabled()) {
        DISPATCHCUDNN2() ;
        if (error == vl::vlSuccess) { return error ; }
        if (error != vl::vlErrorUnsupported) { goto done ; }
        /* this case was not supported by CUDNN -- fallback */
      }
#endif
      DISPATCH2(vl::GPU) ;
      break ;
#endif
  }
#if ENABLE_CUDNN
done:
#endif
  return error ;
}


/* ---------------------------------------------------------------- */
/*                                                  nnconvt_forward */
/* ---------------------------------------------------------------- */

vl::Error
vl::nnconvt_forward(Context& context,
                    Tensor output,
                    Tensor data,
                    Tensor filters,
                    Tensor biases,
                    int upsampleY, int upsampleX,
                    int cropTop, int cropBottom,
                    int cropLeft, int cropRight)
{
  vl::Error error = vlSuccess ;
  size_t dataOffset = data.getHeight()*data.getWidth()*data.getDepth() ;
  size_t outputOffset = output.getHeight()*output.getWidth()*output.getDepth() ;

  // we need to process this down per image as nnconv_backward would otherwise
  // accumulate everything into a single feature field in the output
  for (int image = 0 ; image < data.getSize() ; ++image) {
    Tensor dataSlice(data) ;
    Tensor outputSlice(output) ;

    switch (data.getDataType()) {
      case vlTypeFloat:
        dataSlice.setMemory((float*)data.getMemory() + dataOffset * image) ;
        outputSlice.setMemory((float*)output.getMemory() + outputOffset * image) ;
        break ;
      case vlTypeDouble:
        dataSlice.setMemory((double*)data.getMemory() + dataOffset * image) ;
        outputSlice.setMemory((double*)output.getMemory() + outputOffset * image) ;
        break ;
      default:
        assert(false) ;
    }
    dataSlice.setSize(1) ;
    outputSlice.setSize(1) ;

    error = vl::nnconv_backward(context,
                                outputSlice, Tensor(), Tensor(),
                                Tensor(), filters, dataSlice,
                                upsampleY, upsampleX,
                                cropTop, cropBottom,
                                cropLeft, cropRight) ;
    if (error != vlSuccess) { goto done ; }
  }
  if (biases) {
    error = vl::nnbias_forward(context,
                               output, 1,
                               Tensor(), 0,
                               biases, 1) ;
  }
done:
  return error ;
}

/* ---------------------------------------------------------------- */
/*                                                 nnconvt_backward */
/* ---------------------------------------------------------------- */

vl::Error
vl::nnconvt_backward(Context& context,
                     Tensor derData,
                     Tensor derFilters,
                     Tensor derBiases,
                     Tensor data,
                     Tensor filters,
                     Tensor derOutput,
                     int upsampleY, int upsampleX,
                     int cropTop, int cropBottom,
                     int cropLeft, int cropRight)
{
  vl::Error error = vl::vlSuccess ;

  if (derData) {
    error = vl::nnconv_forward(context,
                                derData, 0,
                                derOutput, 1,
                                filters, Tensor(),
                                upsampleY, upsampleX,
                                cropTop, cropBottom,
                                cropLeft, cropRight) ;
    if (error != vlSuccess) { goto done ; }
  }

  if (derFilters) {
    error = vl::nnconv_backward(context,
                                 Tensor(), derFilters, Tensor(),
                                 derOutput, Tensor(), data,
                                 upsampleY, upsampleX,
                                 cropTop, cropBottom,
                                 cropLeft, cropRight) ;
    if (error != vlSuccess) { goto done ; }
  }

  if (derBiases) {
    error = vl::nnbias_backward(context,
                                 Tensor(), 0,
                                 derBiases, 0,
                                 derOutput, 1) ;
  }

done:
  return error ;
}

// @file nnfullyconnected.cu
// @brief Fully-connected block
// @author Andrea Vedaldi

/*
Copyright (C) 2014-16 Andrea Vedaldi.
All rights reserved.

This file is part of the VLFeat library and is made available under
the terms of the BSD license (see the COPYING file).
*/

#include "nnfullyconnected.hpp"
#include "impl/blashelper.hpp"
#include "impl/copy.hpp"
#include <assert.h>

using namespace vl ;

/* ---------------------------------------------------------------- */
/* nnfullyconnected_forward_impl                                    */
/* ---------------------------------------------------------------- */

template<vl::Device deviceType, vl::Type dataType> vl::Error
nnfullyconnected_forward_impl(Context& context,
                              Tensor output,
                              Tensor data,
                              Tensor filters,
                              Tensor biases)
{
  vl::Error error ;
  typedef typename vl::DataTypeTraits<dataType>::type type ;
  type alpha = 1 ;
  type beta = 0 ;

  if (filters) {
    ptrdiff_t filtersVolume = filters.getHeight() * filters.getWidth() * filters.getDepth() ;
    if (data.getSize() == 1) {
      /* one image in the stack */
      error = vl::impl::blas<deviceType,dataType>::gemv
      (context,
       't',
       filtersVolume, filters.getSize(),
       alpha,
       (type const*)filters.getMemory(), filtersVolume,
       (type const*)data.getMemory(), 1,
       beta,
       (type*)output.getMemory(), 1) ;
      if (error != vl::vlSuccess) { goto done ; }
    } else {
      /* multiple images in the stack */
      error = vl::impl::blas<deviceType,dataType>::gemm
      (context,
       't', 'n',
       filters.getSize(), data.getSize(), filtersVolume,
       alpha,
       (type const*)filters.getMemory(), filtersVolume,
       (type const*)data.getMemory(), filtersVolume,
       beta,
       (type*)output.getMemory(), filters.getSize()) ;
      if (error != vl::vlSuccess) { goto done ; }
    }
  } else {
    error = vl::impl::operations<deviceType,type>::copy
    ((type*)output.getMemory(),
     (type const*)data.getMemory(),
     data.getNumElements()) ;
  }

  if (biases) {
    type beta = 1 ;
    type const* allOnesMemory = (type*) context.getAllOnes(deviceType,
                                                           dataType,
                                                           data.getSize()) ;
    if (allOnesMemory == NULL) {
      error = context.getLastError() ;
      goto done ;
    }
    error = vl::impl::blas<deviceType,dataType>::gemm
    (context, 'n', 'n',
     biases.getNumElements(), data.getSize(), 1,
     alpha,
     (type*)biases.getMemory(), biases.getNumElements(),
     allOnesMemory, 1,
     beta,
     (type*)output.getMemory(), biases.getNumElements()) ;
    if (error != vl::vlSuccess) { goto done ; }
  }
done:
  return context.passError(error, __func__) ;
}

/* ---------------------------------------------------------------- */
/* nnfullyconnected_backward_impl                                   */
/* ---------------------------------------------------------------- */

template<vl::Device deviceType, vl::Type dataType> vl::Error
nnfullyconnected_backward_impl(vl::Context& context,
                               vl::Tensor derData,
                               vl::Tensor derFilters,
                               vl::Tensor derBiases,
                               vl::Tensor data,
                               vl::Tensor filters,
                               vl::Tensor derOutput)
{
  vl::Error error ;
  typedef typename vl::DataTypeTraits<dataType>::type type ;
  type alpha = 1 ;
  type beta = 0 ;

  if (filters) {
    ptrdiff_t filtersVolume = filters.getHeight() * filters.getWidth() * filters.getDepth() ;

    if (derFilters) {
      error = vl::impl::blas<deviceType,dataType>::gemm
      (context,
       'n', 't',
       filtersVolume, filters.getSize(), data.getSize(),
       alpha,
       (type*)data.getMemory(), filtersVolume,
       (type*)derOutput.getMemory(), filters.getSize(),
       beta,
       (type*)derFilters.getMemory(), filtersVolume) ;
      if (error != vl::vlSuccess) { goto done ; }
    }

    if (derData) {
      error = vl::impl::blas<deviceType,dataType>::gemm
      (context,
       'n', 'n',
       filtersVolume, data.getSize(), filters.getSize(),
       alpha,
       (type*)filters.getMemory(), filtersVolume,
       (type*)derOutput.getMemory(), filters.getSize(),
       beta,
       (type*)derData.getMemory(), filtersVolume) ;
      if (error != vl::vlSuccess) { goto done ; }
    }
  } else {
    vl::impl::operations<deviceType,type>::copy
    ((type*)derData.getMemory(),
     (type const*)derOutput.getMemory(),
     derOutput.getNumElements()) ;
  }

  if (derBiases) {
    type const* allOnesMemory = (type*) context.getAllOnes(deviceType,
                                                           dataType,
                                                           derOutput.getSize()) ;
    if (allOnesMemory == NULL) {
      error = context.getLastError() ;
      goto done ;
    }

    error = vl::impl::blas<deviceType, dataType>::gemm
    (context,
     'n', 't',
     1, derOutput.getDepth(), derOutput.getSize(),
     alpha,
     (type*)allOnesMemory, 1,
     (type*)derOutput.getMemory(), derOutput.getDepth(),
     beta,
     (type*)derBiases.getMemory(), 1) ;
    if (error != vl::vlSuccess) { goto done ; }

  }
done:
  return context.passError(error, __func__) ;
}

/* ---------------------------------------------------------------- */
/* nnfullyconnected_forward                                         */
/* ---------------------------------------------------------------- */

#define DISPATCH(deviceType, dataType) \
error = nnfullyconnected_forward_impl<deviceType,dataType> \
(context, output, data, filters, biases) ;

#define DISPATCH2(deviceType) \
switch (dataType) { \
case vlTypeFloat : DISPATCH(deviceType, vlTypeFloat) ; break ; \
IF_DOUBLE(case vlTypeDouble : DISPATCH(deviceType, vlTypeDouble) ; break ;) \
default: assert(false) ; return vlErrorUnknown ; \
}

vl::Error
vl::nnfullyconnected_forward(Context& context,
                             Tensor output,
                             Tensor data,
                             Tensor filters,
                             Tensor biases)
{
  vl::Error error = vl::vlSuccess ;
  vl::Type dataType = data.getDataType() ;

  switch (data.getDeviceType()) {
    default:
      assert(false) ;
      error = vl::vlErrorUnknown ;
      break ;

    case vl::CPU:
      DISPATCH2(vl::CPU) ;
      break ;

#if ENABLE_GPU
    case vl::GPU:
      DISPATCH2(vl::GPU) ;
      break ;
#endif
  }
  return context.passError(error, __func__) ;
}

/* ---------------------------------------------------------------- */
/* nnfullyconnected_backward                                        */
/* ---------------------------------------------------------------- */

#undef DISPATCH
#define DISPATCH(deviceType, dataType) \
error = nnfullyconnected_backward_impl<deviceType,dataType> \
(context, derData, derFilters, derBiases, data, filters, derOutput) ;

vl::Error
vl::nnfullyconnected_backward(vl::Context& context,
                              vl::Tensor derData,
                              vl::Tensor derFilters,
                              vl::Tensor derBiases,
                              vl::Tensor data,
                              vl::Tensor filters,
                              vl::Tensor derOutput)
{
  vl::Error error = vl::vlSuccess ;
  vl::Type dataType = data.getDataType() ;

  switch (derOutput.getDeviceType()) {
    default:
      assert(false) ;
      error = vl::vlErrorUnknown ;
      break ;

    case vl::CPU:
      DISPATCH2(vl::CPU) ;
      break ;

#if ENABLE_GPU
    case vl::GPU:
      DISPATCH2(vl::GPU) ;
      break ;
#endif
  }
  return context.passError(error, __func__) ;
}

