      test.der(@(b) vl_nnconvt(x,f,b), b, dzdy, dzdb, test.range) ;
    end

    function upsample_crop(test,upx,upy,padx1,pady1,padx2,pady2)
      m = 3 ; n = 2 ; k = 3;
      opts = {'upsample',[upy upx],'crop',[pady1 pady2 padx1 padx2]} ;
      x = test.randn(5,6,m,n) ;
      f = test.randn(3,4,k,m) ;
