    multilab = {false true}
  end

  methods (Test)
    function basic(test, multilab, weighed)
      C = 10 ;
      n = 3 ;
      if multilab
        c = reshape(mod(0:3*4*n-1,C)+1, 3, 4, 1, n) ;
      else
        c = reshape([7 2 1],1,1,1,[]) ;
      end
      if weighed
