MLUPE3.m:
function [UPh_MLUPE] = MLUPE3(Psi_sub1,Psi_sub2,ratio_sub1,ratio_sub2,...
    gamma_sub1,gamma_sub2,B_short,B_long,idx_ref)
% 融合判断-根据相位导数方差判断是选择替换还是最大似然融合 -----------wy20210323
UPh_MLUPE = Psi_sub2;%返回的融合相位，初始值默认为长基线解缠相位
B_ratio = B_long/B_short;%将短基线转换到长基线相位
%% 基线个数
% II = 2;
%% 三维数组
[Na,Nr] = size(Psi_sub1);
Psi     = zeros(Na,Nr,2);
ratio   = zeros(Na,Nr,2);
gamma   = zeros(Na,Nr,2);
Phi_candidate = zeros(Na,Nr);
%% 数据传递
Psi(:,:,1)   = Psi_sub1; % 短缠绕相位
Psi(:,:,2)   = Psi_sub2; % 长缠绕相位
ratio(:,:,1) = ratio_sub1; %短基线比
ratio(:,:,2) = ratio_sub2; %长基线比
gamma(:,:,1) = gamma_sub1; %短相干系数
gamma(:,:,2) = gamma_sub2; %长相干系数
%% 相干系数
rou = gamma;
%% 干涉相位概率密度函数PDF
rou1 = reshape(rou(:,:,1),Na,Nr);
rou2 = reshape(rou(:,:,2),Na,Nr);
Psi1 = reshape(Psi(:,:,1), Na, Nr);
Psi2 = reshape(Psi(:,:,2), Na, Nr);

phi_threshold = 1*pi;%将阈值2pi改为6，可以将某些接近2pi却小于2pi的点给挑选出来

%找到长短基线解缠相位的跳变点
%计算短基线相位的跳变点
[pr1,pc1] = size(Psi_sub1);
image_left = Psi_sub1(:,1:pc1-1);
image_right = Psi_sub1(:,2:pc1);
dx = floor(abs(image_left-image_right)/phi_threshold);
image_up = Psi_sub1(1:pr1-1,:);
image_down = Psi_sub1(2:pr1,:);
dy = floor(abs(image_up-image_down)/phi_threshold);
dx(dx>1)=1;
dy(dy>1)=1;
dz1=dx(2:end,:)+dy(:,1:end-1);
dz_l=dx(2:end,:)+dy(:,2:end);
dz3=dx(1:end-1,:)+dy(:,1:end-1);
dz4=dx(1:end-1,:)+dy(:,2:end);
dz_s = dz1 + dz_l + dz3 + dz4;
dz_s(dz_s>1)=1;
[nr_z,nr_c] = size(dz_s);
for i = 2:nr_z-1
    for j = 2:nr_c-1
        if (dz_s(i-1,j) + dz_s(i+1,j) + dz_s(i,j-1) + dz_s(i,j-1)) > 2;
%         if (dz_s(i-1,j) + dz_s(i+1,j) + dz_s(i,j-1) + dz_s(i,j-1)) == 4;            
            dz_s(i,j) = 1;
        end
    end
end

%计算长基线相位的跳变点
[pr2,pc2] = size(Psi_sub2);
image_left = Psi_sub2(:,1:pc2-1);
image_right = Psi_sub2(:,2:pc2);
dx = floor(abs(image_left-image_right)/phi_threshold);
image_up = Psi_sub2(1:pr2-1,:);
image_down = Psi_sub2(2:pr2,:);
dy = floor(abs(image_up-image_down)/phi_threshold);
dx(dx>1)=1;
dy(dy>1)=1;
dz1=dx(2:end,:)+dy(:,1:end-1);
dz2=dx(2:end,:)+dy(:,2:end);
dz3=dx(1:end-1,:)+dy(:,1:end-1);
dz4=dx(1:end-1,:)+dy(:,2:end);
dz_l = dz1 + dz2 + dz3 + dz4;
dz_l(dz_l>1)=1;
[nr_z,nr_c] = size(dz_l);
for i = 2:nr_z-1
    for j = 2:nr_c-1
        if (dz_l(i-1,j) + dz_l(i+1,j) + dz_l(i,j-1) + dz_l(i,j-1)) > 2;
%         if (dz_l(i-1,j) + dz_l(i+1,j) + dz_l(i,j-1) + dz_l(i,j-1)) == 4;
            
            dz_l(i,j) = 1;
        end
    end
end

b = 1;%扩大的搜索区间倍数
p_r = 5;%找一点画概率密度函数
p_c = 5;
h = waitbar(0,'粗融合中...');
for ii = 1:1:Na-1
%        nn = ii+1;
       nn = ii;
       str = ['粗融合中...',num2str(ii/(Na-1)*100),'%'];
       waitbar(ii/(Na-1),h,str)    
    for jj = 1:1:Nr-1
        %逐点判断长短基线的跳变点：
        %如果长短基线都是跳变点或者都不是跳变点，则以长基线为参考基线，长基线解缠相位为搜索中心进行最大似然融合
        %如果短基线不是跳变点，长基线是跳变点，则将短基线转换到长基线域
        %如果短基线是跳变点，长基线不是跳变点，则保留长基线该点的相位
%         mm = jj+1;
        mm = jj;
        %如果短基线不是跳变点，长基线是跳变点，则将短基线转换到长基线域
        if dz_s(ii,jj)==0 && dz_l(ii,jj)==1
            UPh_MLUPE(nn,mm) = Psi_sub1(nn,mm)*B_ratio;
        end
        
        %如果短基线是跳变点，长基线不是跳变点，则保留长基线该点的相位
        if dz_s(ii,jj)==1 && dz_l(ii,jj)==0
            UPh_MLUPE(nn,mm) = Psi_sub2(nn,mm);
        end  
        
        %如果长短基线都是跳变点或者都不是跳变点，则以长基线为参考基线，长基线解缠相位为搜索中心进行最大似然融合
        if (dz_s(ii,jj)==1 && dz_l(ii,jj)==1) || (dz_s(ii,jj)==0 && dz_l(ii,jj)==0) 
        Phi_candidate(nn,mm) = Psi_sub2(nn,mm);
        Lower = Phi_candidate(nn,mm)-b*1*pi; 
        Upper = Phi_candidate(nn,mm)+b*1*pi; 
        search_step = 0.5*5e-2;   
        Phi =  Lower:search_step:Upper;
        JJ     = size(Phi,2);
        % 求最大似然函数
        MLF_PDF = ones(1,JJ);
        c1 = (1 - rou1(nn, mm)^2) / 2 / pi;
        c2 = (1 - rou2(nn, mm)^2) / 2 / pi;
        beta1 = rou1(nn, mm) * cos(Psi1(nn,mm) - Phi*ratio(nn,mm,1));
        beta2 = rou2(nn, mm) * cos(Psi2(nn,mm) - Phi*ratio(nn,mm,2));
        pdf1 = c1 * (sqrt(1 - beta1.^2) + beta1.*acos(-beta1)) ./ ((1 - beta1.^2).^1.5);
        pdf2 = c2 * (sqrt(1 - beta2.^2) + beta2.*acos(-beta2)) ./ ((1 - beta2.^2).^1.5);
        % 最大似然函数MLF
        MLF_PDF = MLF_PDF .* pdf1 .*pdf2;%将pdf1和pdf2相乘
        [~,index] = max(MLF_PDF);       
        % 按比例换算回参考基线
        UPh_MLUPE(nn,mm) = Phi(index) * ratio(nn,mm,idx_ref);% 按比例换算回参考基线

        if nn == p_r && mm == p_c     
             figure;plot(Phi,pdf1,'r');hold on 
             plot(Phi,pdf2,'b')
        end
        if nn == p_r && mm == p_c  
            mlf = MLF_PDF;
            figure;plot(Phi,mlf)
        end 

        end
   end
end
end

MLUPE_PDV.m:
function [UPh_MLUPE] = MLUPE_PDV(Psi_sub1,Psi_sub2,short_PDV,long_PDV,ratio_sub1,ratio_sub2,...
    gamma_sub1,gamma_sub2,B_short,B_long,idx_ref)
% 融合判断-根据相位导数方差判断是选择替换还是最大似然融合 -----------wy20210323
UPh_MLUPE = Psi_sub2;%返回的融合相位，初始值默认为长基线解缠相位
B_ratio = B_long/B_short;%将短基线转换到长基线相位
%% 基线个数
% II = 2;
%% 三维数组
[Na,Nr] = size(Psi_sub1);
Psi     = zeros(Na,Nr,2);
ratio   = zeros(Na,Nr,2);
gamma   = zeros(Na,Nr,2);
Phi_candidate = zeros(Na,Nr);
%% 数据传递
Psi(:,:,1)   = Psi_sub1; % 短缠绕相位
Psi(:,:,2)   = Psi_sub2; % 长缠绕相位
ratio(:,:,1) = ratio_sub1; %短基线比
ratio(:,:,2) = ratio_sub2; %长基线比
gamma(:,:,1) = gamma_sub1; %短相干系数
gamma(:,:,2) = gamma_sub2; %长相干系数
%% 相干系数
rou = gamma;
%% 干涉相位概率密度函数PDF
rou1 = reshape(rou(:,:,1),Na,Nr);
rou2 = reshape(rou(:,:,2),Na,Nr);
Psi1 = reshape(Psi(:,:,1), Na, Nr);
Psi2 = reshape(Psi(:,:,2), Na, Nr);

%找出短基线相位梯度大的地方并标记
dz_s = pdv_jump_mark(short_PDV,Psi_sub1);

%找出长基线相位梯度大的地方并标记
dz_l = pdv_jump_mark(long_PDV,Psi_sub2);

b = 1;%扩大的搜索区间倍数
% p_r = 5;%找一点画概率密度函数
% p_c = 5;
h = waitbar(0,'粗融合中...');
for ii = 1:1:Na-1
       nn = ii;
       str = ['粗融合中...',num2str(ii/(Na-1)*100),'%'];
       waitbar(ii/(Na-1),h,str)    
    for jj = 1:1:Nr-1
        %逐点判断长短基线的跳变点：
        %如果长短基线都是跳变点或者都不是跳变点，则以长基线为参考基线，长基线解缠相位为搜索中心进行最大似然融合
        %如果短基线不是跳变点，长基线是跳变点，则将短基线转换到长基线域
        %如果短基线是跳变点，长基线不是跳变点，则保留长基线该点的相位
        mm = jj;
        %如果短基线不是跳变点，长基线是跳变点，则将短基线转换到长基线域
        if dz_s(ii,jj)==0 && dz_l(ii,jj)==1
            UPh_MLUPE(nn,mm) = Psi_sub1(nn,mm)*B_ratio;
        end
        
        %如果短基线是跳变点，长基线不是跳变点，则保留长基线该点的相位
        if dz_s(ii,jj)==1 && dz_l(ii,jj)==0
            UPh_MLUPE(nn,mm) = Psi_sub2(nn,mm);
        end  
        
        %如果长短基线都是跳变点或者都不是跳变点，则以长基线为参考基线，长基线解缠相位为搜索中心进行最大似然融合
        if (dz_s(ii,jj)==1 && dz_l(ii,jj)==1) || (dz_s(ii,jj)==0 && dz_l(ii,jj)==0) 
        Phi_candidate(nn,mm) = Psi_sub2(nn,mm);
        Lower = Phi_candidate(nn,mm)-b*1*pi; 
        Upper = Phi_candidate(nn,mm)+b*1*pi; 
        search_step = 0.5*5e-2;   
        Phi =  Lower:search_step:Upper;
        JJ     = size(Phi,2);
        % 求最大似然函数
        MLF_PDF = ones(1,JJ);
        c1 = (1 - rou1(nn, mm)^2) / 2 / pi;
        c2 = (1 - rou2(nn, mm)^2) / 2 / pi;
        beta1 = rou1(nn, mm) * cos(Psi1(nn,mm) - Phi*ratio(nn,mm,1));
        beta2 = rou2(nn, mm) * cos(Psi2(nn,mm) - Phi*ratio(nn,mm,2));
        pdf1 = c1 * (sqrt(1 - beta1.^2) + beta1.*acos(-beta1)) ./ ((1 - beta1.^2).^1.5);
        pdf2 = c2 * (sqrt(1 - beta2.^2) + beta2.*acos(-beta2)) ./ ((1 - beta2.^2).^1.5);
        % 最大似然函数MLF
        MLF_PDF = MLF_PDF .* pdf1 .*pdf2;%将pdf1和pdf2相乘
        [~,index] = max(MLF_PDF);       
        % 按比例换算回参考基线
        UPh_MLUPE(nn,mm) = Phi(index) * ratio(nn,mm,idx_ref);% 按比例换算回参考基线

%         if nn == p_r && mm == p_c     
%              figure;plot(Phi,pdf1,'r--');hold on 
%              plot(Phi,pdf2,'b')
%         end
%         if nn == p_r && mm == p_c  
%             mlf = MLF_PDF;
%             figure;plot(Phi,mlf)
%         end 

        end
   end
end
end

MSE.m:
function mse = MSE(phase_filter, phase_real)
%计算平均均方误差
%输入：滤波后和真实相位矩阵
%输出：MSE,单位为相位，rad
j = sqrt(-1);
error = phase_filter - phase_real;
square_error = angle(exp(j*error)).^2;
mse = mean(mean(square_error));
end

NL_Adapt_Filter.m:
function phase_filter = NL_Adapt_Filter(phase,h)
% 基于局部频率估计的斜坡自适应非局域滤波2019LS
% FFT+CZT 提升局部频率估计的精度
% i-direction: 行方向
% j-direction: 列方向
% Inputs: 原始干涉相位矩阵、行数、列数
% Outputs: 滤波后干涉相位矩阵
j=sqrt(-1);
% %----------------- display information -------------------%
% display([repmat('-', 1, 8),' phase filter ',repmat('-', 1, 8)])
% display(['method:             ','SAPF'])
% display(repmat('-', 1, 30))
%% 窗参数
% 当干涉相位方差变化范围不大时，估计窗size可取9，11，13，基线400m时，取9较优
% winsize_e_i = 21;           %估计窗i方向尺寸
% winsize_e_j = 21;           %估计窗j方向尺寸
% winsize_f_i = 23;  %滤波窗i方向尺寸
% winsize_f_j = 23;  %滤波窗j方向尺寸
winsize_e_i = 23;           %估计窗i方向尺寸
winsize_e_j =23;           %估计窗j方向尺寸
winsize_f_i = 21;  %滤波窗i方向尺寸
winsize_f_j = 21;  %滤波窗j方向尺寸0104修改
wine_i = (winsize_e_i-1)/2; %估计窗i方向半径
wine_j = (winsize_e_j-1)/2; %估计窗j方向半径
winf_i = (winsize_f_i-1)/2; %滤波窗i方向半径
winf_j = (winsize_f_j-1)/2; %滤波窗j方向半径
[size_i,size_j]=size(phase);

%% 扩充相位矩阵
% 扩充估计相位矩阵
phase_update = zeros(size_i+winsize_e_i-1,size_j+winsize_e_j-1);             
[Ni,Nj] = size(phase_update);
phase_update(wine_i+1:Ni-wine_i,wine_j+1:Nj-wine_j) = phase;
% flipud:矩阵上下交换，fliplr:矩阵左右交换
phase_update(1:wine_i,1:Nj) = flipud(phase_update(wine_i+1:2*wine_i,1:Nj)); 
phase_update(1:Ni,1:wine_j) = fliplr(phase_update(1:Ni,wine_j+1:2*wine_j));  
phase_update(Ni-wine_i+1:Ni,1:Nj) = flipud(phase_update(Ni-2*wine_i+1:Ni-wine_i,1:Nj));
phase_update(1:Ni,Nj-wine_j+1:Nj) = fliplr(phase_update(1:Ni,Nj-2*wine_j+1:Nj-wine_j));
% 将相位转化为复数
phase_update = exp(j*phase_update);     
%% 局部频率估计参数
phase_linear = zeros(Ni,Nj); % 线形相位矩阵
phase_filter = zeros(Ni,Nj); % 滤波后相位矩阵
nn = 32;                     % 2D FFT点数
mm = 32;                     % CZT点数
mn = mm*nn;                  % 频谱总分辨率（mn*mn）
phase_estimation = zeros(winsize_e_i,winsize_e_j); %估计窗内相位矩阵
tempi = (0:winsize_f_i-1)';  % 行线形相位网格
tempj = 0:winsize_f_j-1;     % 列线形相位网格
w0 = exp(-j*2*pi/mn);        % CZT参数
%% 自适应滤波
%% 非局域参数LS2019
wb = waitbar(0,'phase filtering ...');
for ii = wine_i+1:Ni-wine_i
  for jj = wine_j+1:Nj-wine_j
      phase_estimation(1:winsize_e_i,1:winsize_e_j) = phase_update(ii-wine_i:ii+wine_i,jj-wine_j:jj+wine_j);
      % FFT频率估计
      phase_2fft = fftshift(fft2(phase_estimation,nn,nn)); %窗口内2DFFT
      [val_j,ind_j] = max(max(abs(phase_2fft)));      %ind_j最大值列号 
      [val_i,ind_i] = max(abs(phase_2fft(:,ind_j)));  %ind_i最大值行号 
      fi = double(ind_i-nn/2-2)/nn;
      fj = double(ind_j-nn/2-2)/nn;
      ei = exp(j*2*pi*fi);
      ej = exp(j*2*pi*fj);
      % CZT频谱主瓣精细估计
      phasef_czt1 = czt(phase_estimation,3*mm,w0,ei); %i(行)方向CZT,czt按列计算
      phasef_czt2 = czt(phasef_czt1.',3*mm,w0,ej);    %j(列)方向CZT
      phasef_czt2 = phasef_czt2.';
      [val_j,ind_j] = max(max(abs(phasef_czt2)));
      [val_i,ind_i] = max(abs(phasef_czt2(:,ind_j)));
      movei = double(ind_i-1)/mn;  %i(行)方向细化后偏移量
      movej = double(ind_j-1)/mn;  %j(列)方向细化后偏移量
      fii = fi+movei;
      fjj = fj+movej;       %CZT提升分辨率后，频谱峰值位置
      ei = exp(j*2*pi*fii); %i(行)方向局部频率（指数）
      ej = exp(j*2*pi*fjj); %j(列)方向局部频率（指数）
      % 线性相位
      phase_linear(ii-winf_i:ii+winf_i,jj-winf_j:jj+winf_j) = ei.^tempi*(ej.^tempj);
      % 初相,sum(sum()) or mean(mean())
      phase_0_matrix = phase_update(ii-winf_i:ii+winf_i,jj-winf_j:jj+winf_j).*...
                       conj(phase_linear(ii-winf_i:ii+winf_i,jj-winf_j:jj+winf_j));
%       %均值滤波
%        phase_0 =  mean(mean(phase_0_matrix)); %均值滤波  
      %NL滤波
      ds=3;%邻域窗口半径
      Ds=winf_i;%搜索窗口半径
%       h=1;%高斯函数平滑参数
      kernel=ones(2*ds+1,2*ds+1);
      kernel=kernel./((2*ds+1)*(2*ds+1));
      h2=h*h;

%%%%%%%%%%%
%         W1= PaddedImg(ii-ds:ii+ds,jj-ds:jj+ds);%邻域窗口1
        W1=phase_0_matrix(Ds-ds+1:Ds+ds+1,Ds-ds+1:Ds+ds+1) ;%邻域窗口1
        wmax=0;
        average=0;
        sweight=0;
        %%搜索窗口
        rmin = ds+1;
        rmax = 2*Ds+1-ds;
        smin = ds+1;
        smax = 2*Ds+1-ds;
        for r=rmin:rmax
            for s=smin:smax
                W2=phase_0_matrix(r-ds:r+ds,s-ds:s+ds);%邻域窗口2
                 Dist2=sum(sum(kernel.*(W1-W2).*(W1-W2)));%邻域间距离
%                   Dist2=sum(sum(kernel.*(angle(W1)-angle(W2)).*(angle(W1)-angle(W2))));%邻域间距离
                w=exp(-Dist2/h2);
                if(w>wmax)
                    wmax=w;
                end
                sweight=sweight+w;
                average=average+w*phase_0_matrix(r,s);
            end
        end
%         average=average+wmax*phase_0_matrix(ii,jj);%自身取最大权值
%         sweight=sweight+wmax;
       phase_0=average/sweight;


      % 初相 + 线性相位 
      phase_filter(ii,jj) = phase_0 * phase_linear(ii,jj);
      Local_frequency(ii,jj)=fjj;
  end
   str = ['自适应滤波进行中',num2str(fix((100*ii/(Ni-2*wine_i)))),'%'];
 waitbar(ii/(Ni-2*wine_i),wb,str);
 pause(1);
end
close(wb);
%% 取复相角(rad),取有效范围
phase_filter = angle(phase_filter);
phase_filter = phase_filter(wine_i+1:Ni-wine_i,wine_j+1:Nj-wine_j);
%% 输出
% figure;
% imagesc(phase_filter)
% % axis xy
% colormap(jet)
% title('interferometric phase (SAPF)','fontWeight','Bold')
clear phase_update phase_linear phase_estimation;
end

